/* Ungesendetes Feedback auf der Abgabe-Seite nicht kommentarlos verlieren (24. 11. 2026): beim Verlassen nachfragen */
let fbWeiter=null;
function fbOffen(){return st.view==="abgabe"&&st.p&&(String(st.p.entwurf||"").trim()||(ANH.fbl||[]).length)}
function fbWarnen(view,p){fbWeiter={view,p};const u=U(st.p.u);modal(`<h2>Feedback noch nicht gesendet</h2><p>Dein Feedback an ${esc(u.vn)} ist noch nicht gesendet. Was soll damit passieren?</p><div class="actions"><button class="btn primary" data-act="fbw-senden">Senden und weiter</button><button class="btn" data-act="fbw-weg">Verwerfen und weiter</button><button class="btn ghost" data-close-btn>Hierbleiben</button></div>`)}
addEventListener("beforeunload",e=>{if(fbOffen()){e.preventDefault();e.returnValue=""}});
function go(view,p={}){if(fbOffen()&&!(view==="abgabe"&&p&&p.id===st.p.id&&p.u===st.p.u)){fbWarnen(view,p);return}
